      ro: ["Centru pentru decorticarea și sortarea cafelei Arabica", "Locație importantă pentru pregătirea exportului de cafea", "Situată în regiunea centrală, lângă orașul Gitega", "Procesează recolte de la numeroase cooperative regionale", "Dispune de laboratoare pentru controlul calității și cupping", "Contribuie la creșterea valorii de piață a cafelei burundeze"],
      en: ["Central hub for the hulling and grading of Arabica coffee", "Key facility for preparing coffee exports for international markets", "Located in the central region near the city of Gitega", "Processes harvests from numerous regional cooperatives", "Features specialized labs for quality control and cupping", "Helps increase the market value of Burundian coffee products"],
      es: ["Inauguración: 2010.", "Procesamiento anual: 5.000 toneladas de café verde.", "Número de trabajadores (estacional): 300.", "Países de exportación: Europa, Norteamérica.", "Variedad de café: Arábica.", "Capacidad de ampliación: hasta 10.000 toneladas."],
      pt: ["Inauguração: 2010.", "Processamento anual: 5.000 toneladas de café verde.", "Número de trabalhadores (sazonal): 300.", "Países de exportação: Europa, América do Norte.", "Variedade de café: Arábica.", "Capacidade de expansão: até 10.000 toneladas."],
      fr: ["Ouverture : 2010.", "Traitement annuel : 5 000 tonnes de café vert.", "Nombre d'ouvriers (saisonniers) : 300.", "Pays d'exportation : Europe, Amérique du Nord.", "Variété de café : Arabica.", "Capacité d'extension : jusqu'à 10 000 tonnes."],
